EOF
cat > parse/event.go <<'EOF'
// Package parse reads the JSON event stream produced by `go test -json`
// and aggregates it into per-package summaries.
package parse

import (
	"regexp"
	"strings"
	"time"
)

// Action is the kind of event reported by the go test JSON stream.
type Action string

const (
	ActionRun    Action = "run"
	ActionPause  Action = "pause"
	ActionCont   Action = "cont"
	ActionPass   Action = "pass"
	ActionBench  Action = "bench"
	ActionFail   Action = "fail"
	ActionOutput Action = "output"
	ActionSkip   Action = "skip"
	ActionStart  Action = "start"
)

// Event mirrors a single line of `go test -json` output.
type Event struct {
	Time    time.Time
	Action  Action
	Package string
	Test    string
	Elapsed float64
	Output  string
}

var coverRe = regexp.MustCompile(`\d{1,3}\.\d%`)

// IsPanic reports whether the output line is the start of a panic trace.
func (e *Event) IsPanic() bool {
	return strings.HasPrefix(e.Output, "panic: ")
}

// IsCached reports whether the output line is a cached package result line.
func (e *Event) IsCached() bool {
	return strings.HasPrefix(e.Output, "ok  \t") && strings.Contains(e.Output, "\t(cached)")
}

// NoTestsToRun reports whether the output line signals a package whose test
// binary contained no tests to run.
func (e *Event) NoTestsToRun() bool {
	return strings.HasPrefix(e.Output, "ok  \t") && strings.HasSuffix(e.Output, "[no tests to run]\n")
}

// NoTestFiles reports whether the output line signals a package without test files.
func (e *Event) NoTestFiles() bool {
	return strings.HasPrefix(e.Output, "?   \t") && strings.HasSuffix(e.Output, "[no test files]\n")
}

// Coverage extracts a coverage percentage (e.g. "45.6%") from the output line.
func (e *Event) Coverage() (string, bool) {
	if !strings.Contains(e.Output, "coverage:") || !strings.Contains(e.Output, "of statements") {
		return "", false
	}
	m := coverRe.FindString(e.Output)
	if m == "" {
		return "", false
	}
	return m, true
}

// isUpdateLine reports whether the raw output line is a test runner progress
// marker ("=== RUN", "=== PAUSE", "=== CONT") that carries no information.
func isUpdateLine(s string) bool {
	return strings.HasPrefix(s, "=== RUN   ") ||
		strings.HasPrefix(s, "=== PAUSE ") ||
		strings.HasPrefix(s, "=== CONT  ")
}

// DiscardFollow reports whether the output should be hidden in follow mode.
func (e *Event) DiscardFollow() bool {
	s := strings.TrimSpace(e.Output)
	for _, p := range []string{"=== RUN   ", "=== PAUSE ", "=== CONT  ", "--- PASS: ", "--- SKIP: "} {
		if strings.HasPrefix(s, p) {
			return true
		}
	}
	if e.Test == "" && (s == "PASS" || s == "FAIL") {
		return true
	}
	return false
}
EOF
echo done"}

