	return strings.HasPrefix(e.Output, "ok  \t") && strings.HasSuffix(e.Output, "[no tests to run]\n")
}

// NoTestFiles reports whether the output line signals a package without test files.
func (e *Event) NoTestFiles() bool {
	return strings.HasPrefix(e.Output, "?   \t") && strings.HasSuffix(e.Output, "[no test files]\n")
}

// Coverage extracts a coverage percentage (e.g. "45.6%") from the output line.
func (e *Event) Coverage() (string, bool) {
	if !strings.Contains(e.Output, "coverage:") || !strings.Contains(e.Output, "of statements") {
		return "", false
	}
	m := coverRe.FindString(e.Output)
	if m == "" {
		return "", false
	}
	return m, true
}

// isUpdateLine reports whether the raw output line is a test runner progress
// marker ("=== RUN", "=== PAUSE", "=== CONT") that carries no information.
func isUpdateLine(s string) bool {
	return strings.HasPrefix(s, "=== RUN   ") ||
		strings.HasPrefix(s, "=== PAUSE ") ||
		strings.HasPrefix(s, "=== CONT  ")
}

// DiscardFollow reports whether the output should be hidden in follow mode.
func (e *Event) DiscardFollow() bool {
	s := strings.TrimSpace(e.Output)
	for _, p := range []string{"=== RUN   ", "=== PAUSE ", "=== CONT  ", "--- PASS: ", "--- SKIP: "} {
		if strings.HasPrefix(s, p) {
			return true
		}
	}
	if e.Test == "" && (s == "PASS" || s == "FAIL") {
		return true
	}
	return false
}
