func Process(r io.Reader, opts Options) (*Summary, error) {
	sum := &Summary{byName: map[string]*Package{}}
	sc := bufio.NewScanner(r)
	started := false
	for sc.Scan() {
		line := sc.Bytes()
		var e Event
		if err := json.Unmarshal(line, &e); err != nil {
			if !started {
				// Tolerate (and echo) any non-JSON preamble such as build output.
				if opts.Follow != nil {
					fmt.Fprintln(opts.Follow, string(line))
				}
				continue
			}
			var syntaxErr *json.SyntaxError
			if errors.As(err, &syntaxErr) {
				return nil, ErrNotParsable
			}
			return nil, err
		}
		started = true

		if opts.Follow != nil && e.Action == ActionOutput && !e.DiscardFollow() {
			if opts.IncludeTimestamp {
				fmt.Fprint(opts.Follow, e.Time.Format(time.RFC3339), " ")
			}
			fmt.Fprint(opts.Follow, e.Output)
		}

		p := sum.pkg(e.Package)
		p.addEvent(&e)

		if opts.Progress != nil && e.Test == "" && (e.Action == ActionPass || e.Action == ActionFail) {
			status := strings.ToUpper(string(e.Action))
			suffix := ""
			if p.NoTestFiles {
				status = "SKIP"
				suffix += " [no test files]"
			}
			if p.NoTests {
				status = "SKIP"
				suffix += " [no tests to run]"
			}
			label := status
			if opts.ProgressStatus != nil {
				label = opts.ProgressStatus(status)
			}
			fmt.Fprintf(opts.Progress, "[%s]\t%9.2fs\t%s%s\n", label, e.Elapsed, e.Package, suffix)
		}
	}
	if err := sc.Err(); err != nil {
		return nil, fmt.Errorf("received scanning error: %w", err)
	}
	if !started {
		return nil, ErrNotParsable
	}
	return sum, nil
