// Package ui contains the terminal rendering primitives used by tparse:
// cell-width measurement, text wrapping, boxes and tables.
package ui

import (
	"strings"
	"unicode"
	"unicode/utf8"
)

// RuneWidth returns the number of terminal cells needed to display r.
func RuneWidth(r rune) int {
	switch {
	case r == 0 || r < 0x20 || (r >= 0x7f && r < 0xa0):
		return 0
	case r == 0x200b || r == 0x200c || r == 0x200d || r == 0x2060 || r == 0xfeff:
		return 0
	case unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || unicode.Is(unicode.Cf, r):
		return 0
	case isWide(r):
