// StringWidth returns the display width of s, ignoring ANSI escape sequences.
func StringWidth(s string) int {
	w := 0
	inEsc := false
	for i := 0; i < len(s); {
		c := s[i]
		if inEsc {
			// CSI sequences end with a byte in the 0x40..0x7e range.
			if c >= 0x40 && c <= 0x7e {
				inEsc = false
			}
			i++
			continue
		}
		if c == 0x1b {
			inEsc = true
			i++
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		w += RuneWidth(r)
		i += size
	}
	return w
}

// Lines splits s on newlines and also returns the widest line.
func Lines(s string) ([]string, int) {
	lines := strings.Split(s, "\n")
	widest := 0
	for _, l := range lines {
		if w := StringWidth(l); w > widest {
			widest = w
		}
	}
	return lines, widest
