package ui

import (
	"bytes"
	"strings"
	"unicode"
	"unicode/utf8"
)

// Wrap wraps text at the given cell limit, preferring to break on spaces and
// hyphens but hard-breaking words that are longer than a whole line. ANSI
// escape sequences are preserved and do not count towards the width.
func Wrap(s string, limit int) string {
	if limit < 1 {
		return s
	}

	var (
		buf      bytes.Buffer
		word     bytes.Buffer
		space    bytes.Buffer
		curWidth int // written width of the current line
		wordLen  int // display width of the pending word
		b        = []byte(s)
		i        = 0
	)

	addSpace := func() {
		curWidth += space.Len()
		buf.Write(space.Bytes())
		space.Reset()
	}
	addWord := func() {
		if word.Len() == 0 {
			return
		}
		addSpace()
		curWidth += wordLen
		buf.Write(word.Bytes())
		word.Reset()
		wordLen = 0
	}
	addNewline := func() {
		buf.WriteByte('\n')
		curWidth = 0
		space.Reset()
	}

	for i < len(b) {
		c := b[i]

		// Escape sequences are carried along with the word, width-free.
		if c == 0x1b {
			j := i + 1
			if j < len(b) && b[j] == '[' {
				j++
				for j < len(b) && !(b[j] >= 0x40 && b[j] <= 0x7e) {
					j++
				}
				if j < len(b) {
					j++
				}
			} else if j < len(b) {
				j++
			}
			word.Write(b[i:j])
			i = j
			continue
		}

		if c >= utf8.RuneSelf {
			r, size := utf8.DecodeRune(b[i:])
			cluster := b[i : i+size]
			width := RuneWidth(r)
			i += size

			switch {
			case r != utf8.RuneError && unicode.IsSpace(r) && r != 0xa0:
				addWord()
				space.Write(cluster)
			default:
				if wordLen+width > limit {
					// Hard-wrap a word that can never fit on one line.
					addWord()
				}
				word.Write(cluster)
				wordLen += width
				if curWidth+wordLen+space.Len() > limit {
					addNewline()
				}
			}
			continue
		}

		r := rune(c)
		switch {
		case r == '\n':
			if wordLen == 0 {
				if curWidth+space.Len() > limit {
					curWidth = 0
				} else {
					// preserve trailing whitespace
					buf.Write(space.Bytes())
				}
				space.Reset()
			}
			addWord()
			addNewline()
		case unicode.IsSpace(r):
			addWord()
			space.WriteByte(c)
		case r == '-':
			addSpace()
			if curWidth+wordLen >= limit {
				// The breakpoint does not fit; keep it with the word.
				word.WriteByte(c)
				wordLen++
			} else {
				addWord()
				buf.WriteByte(c)
				curWidth++
			}
		default:
			if curWidth == limit {
				addNewline()
			}
			word.WriteByte(c)
			wordLen++
			if wordLen == limit {
				// Hard-wrap a word that can never fit on one line.
				addWord()
			}
			if curWidth+wordLen+space.Len() > limit {
				addNewline()
			}
		}
		i++
	}

	if word.Len() != 0 {
		if curWidth+space.Len() > limit {
			buf.WriteByte('\n')
		}
		addSpace()
	}
	buf.Write(word.Bytes())

	return buf.String()
}

// RenderBlock mimics rendering text through a fixed-width style: tabs are
// expanded to four spaces, lines are wrapped at width and every line is
// padded with spaces to the common width.
func RenderBlock(s string, width int) string {
	s = strings.ReplaceAll(s, "\t", "    ")
	s = strings.ReplaceAll(s, "\r\n", "\n")
	if width > 0 {
		s = Wrap(s, width)
	}
	lines, widest := Lines(s)
	if width > widest {
		widest = width
	}
	for i, l := range lines {
		if short := widest - StringWidth(l); short > 0 {
			lines[i] = l + strings.Repeat(" ", short)
		}
	}
	return strings.Join(lines, "\n")
}
