package ui

import "strings"

// Style is a minimal SGR text style. A zero Style renders text unchanged.
type Style struct {
	seq     string
	enabled bool
}

// NewStyle returns a style emitting the given SGR parameter sequence
// (e.g. "91" for bright red, "38;5;103" for a 256-colour foreground).
func NewStyle(seq string, enabled bool) Style {
	return Style{seq: seq, enabled: enabled}
}

// Render styles s line by line; tabs are expanded to four spaces.
func (st Style) Render(s string) string {
	s = strings.ReplaceAll(s, "\t", "    ")
	s = strings.ReplaceAll(s, "\r\n", "\n")
	if !st.enabled || st.seq == "" {
		return s
	}
	lines := strings.Split(s, "\n")
	for i, l := range lines {
		lines[i] = "\x1b[" + st.seq + "m" + l + "\x1b[0m"
	}
	return strings.Join(lines, "\n")
}

// BorderChars describes the glyphs used to draw a box or table border.
type BorderChars struct {
	Top, Bottom, Left, Right                       string
	TopLeft, TopRight, BottomLeft, BottomRight     string
	MiddleLeft, MiddleRight, Middle                string
	MiddleTop, MiddleBottom                        string
}

// ThickBorder is a heavy box-drawing border.
var ThickBorder = BorderChars{
	Top: "━", Bottom: "━", Left: "┃", Right: "┃",
	TopLeft: "┏", TopRight: "┓", BottomLeft: "┗", BottomRight: "┛",
	MiddleLeft: "┣", MiddleRight: "┫", Middle: "╋", MiddleTop: "┳", MiddleBottom: "┻",
}

// RoundedBorder is a light box-drawing border with rounded corners.
var RoundedBorder = BorderChars{
	Top: "─", Bottom: "─", Left: "│", Right: "│",
	TopLeft: "╭", TopRight: "╮", BottomLeft: "╰", BottomRight: "╯",
	MiddleLeft: "├", MiddleRight: "┤", Middle: "┼", MiddleTop: "┬", MiddleBottom: "┴",
}

// HiddenBorder draws the border using spaces.
var HiddenBorder = BorderChars{
	Top: " ", Bottom: " ", Left: " ", Right: " ",
	TopLeft: " ", TopRight: " ", BottomLeft: " ", BottomRight: " ",
	MiddleLeft: " ", MiddleRight: " ", Middle: " ", MiddleTop: " ", MiddleBottom: " ",
}

// MarkdownBorder draws a GitHub flavoured markdown table.
var MarkdownBorder = BorderChars{
	Top: "-", Bottom: "-", Left: "|", Right: "|",
	TopLeft: "|", TopRight: "|", BottomLeft: "|", BottomRight: "|",
	MiddleLeft: "|", MiddleRight: "|", Middle: "|", MiddleTop: "|", MiddleBottom: "|",
}

// Box draws content inside a bordered box with horizontal padding.
func Box(content string, border BorderChars, borderStyle Style, hpad int) string {
	lines, widest := Lines(content)
	inner := widest + 2*hpad
	pad := strings.Repeat(" ", hpad)
	var sb strings.Builder
	sb.WriteString(borderStyle.Render(border.TopLeft + strings.Repeat(border.Top, inner) + border.TopRight))
	sb.WriteByte('\n')
	for _, l := range lines {
		sb.WriteString(borderStyle.Render(border.Left))
		sb.WriteString(pad)
		sb.WriteString(l)
		if short := widest - StringWidth(l); short > 0 {
			sb.WriteString(strings.Repeat(" ", short))
		}
		sb.WriteString(pad)
		sb.WriteString(borderStyle.Render(border.Right))
		sb.WriteByte('\n')
	}
	sb.WriteString(borderStyle.Render(border.BottomLeft + strings.Repeat(border.Bottom, inner) + border.BottomRight))
	return sb.String()
}
EOF
cat > ui/table.go <<'EOF'
package ui

import "strings"

// Align is a horizontal cell alignment.
type Align int

const (
	AlignLeft Align = iota
	AlignCenter
	AlignRight
)

// Table renders rows of text cells with a border.
type Table struct {
	Headers []string
	Rows    [][]string
	// Align holds the alignment of each data column. Headers are centred.
	Align  []Align
	Border BorderChars
	// BorderTop / BorderBottom toggle the outer horizontal rules.
	BorderTop, BorderBottom bool
}

func alignLine(l string, width int, a Align) string {
	short := width - StringWidth(l)
	if short <= 0 {
		return l
	}
	switch a {
	case AlignRight:
		return strings.Repeat(" ", short) + l
	case AlignCenter:
		left := short / 2
		right := left + short%2
		return strings.Repeat(" ", left) + l + strings.Repeat(" ", right)
	default:
		return l + strings.Repeat(" ", short)
	}
}

// renderCell pads a cell with one space either side, aligns it within width
// and extends it to height lines.
func renderCell(text string, width, height int, a Align) []string {
	text = strings.ReplaceAll(text, "\t", "    ")
	lines := strings.Split(text, "\n")
	out := make([]string, 0, height)
	for _, l := range lines {
		out = append(out, alignLine(" "+l+" ", width, a))
	}
	for len(out) < height {
		out = append(out, strings.Repeat(" ", width))
	}
	if len(out) > height {
		out = out[:height]
	}
	return out
}

// Render draws the table. The result never ends with a newline.
func (t Table) Render() string {
	ncols := len(t.Headers)
	for _, r := range t.Rows {
		if len(r) > ncols {
			ncols = len(r)
		}
	}
	headers := make([]string, ncols)
	copy(headers, t.Headers)

	widths := make([]int, ncols)
	for i, h := range headers {
		_, w := Lines(strings.ReplaceAll(h, "\t", "    "))
		widths[i] = w + 2
	}
	heights := make([]int, len(t.Rows))
	for r, row := range t.Rows {
		heights[r] = 1
		for c := 0; c < ncols; c++ {
			cell := ""
			if c < len(row) {
				cell = row[c]
			}
			lines, w := Lines(strings.ReplaceAll(cell, "\t", "    "))
			if w+2 > widths[c] {
				widths[c] = w + 2
			}
			if len(lines) > heights[r] {
				heights[r] = len(lines)
			}
		}
	}

	colAlign := func(c int) Align {
		if c < len(t.Align) {
			return t.Align[c]
		}
		return AlignLeft
	}

	rule := func(left, mid, right, fill string) string {
		var sb strings.Builder
		sb.WriteString(left)
		for i, w := range widths {
			sb.WriteString(strings.Repeat(fill, w))
			if i < ncols-1 {
				sb.WriteString(mid)
			}
		}
		sb.WriteString(right)
		return sb.String()
	}

	var lines []string
	b := t.Border
	if t.BorderTop {
		lines = append(lines, rule(b.TopLeft, b.MiddleTop, b.TopRight, b.Top))
	}
	// header row
	{
		var sb strings.Builder
		sb.WriteString(b.Left)
		for i, h := range headers {
			cell := renderCell(h, widths[i], 1, AlignCenter)
			sb.WriteString(cell[0])
			if i < ncols-1 {
				sb.WriteString(b.Left)
			}
		}
		sb.WriteString(b.Right)
		lines = append(lines, sb.String())
		lines = append(lines, rule(b.MiddleLeft, b.Middle, b.MiddleRight, b.Bottom))
	}
	for r, row := range t.Rows {
		h := heights[r]
		cells := make([][]string, ncols)
		for c := 0; c < ncols; c++ {
			cell := ""
			if c < len(row) {
				cell = row[c]
			}
			cells[c] = renderCell(cell, widths[c], h, colAlign(c))
		}
		for ln := 0; ln < h; ln++ {
			var sb strings.Builder
			sb.WriteString(b.Left)
			for c := 0; c < ncols; c++ {
				sb.WriteString(cells[c][ln])
				if c < ncols-1 {
					sb.WriteString(b.Left)
				}
			}
			sb.WriteString(b.Right)
			lines = append(lines, sb.String())
		}
	}
	if t.BorderBottom {
		lines = append(lines, rule(b.BottomLeft, b.MiddleBottom, b.BottomRight, b.Bottom))
	}
	return strings.Join(lines, "\n")
}
EOF
