{"command":"cd /workspace && gofmt -w ui parse && cat > report.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"sort"
	"strings"

	"tparse/parse"
	"tparse/ui"
)

// Format selects the table rendering style.
type Format string

const (
	FormatBasic    Format = "basic"
	FormatPlain    Format = "plain"
	FormatMarkdown Format = "markdown"
)

// SortKey selects the attribute used to order packages.
type SortKey string

const (
	SortName    SortKey = "name"
	SortElapsed SortKey = "elapsed"
	SortCover   SortKey = "cover"
)

// Reporter renders a parsed summary.
type Reporter struct {
	Color       bool
	Format      Format
	Sort        SortKey
	ShowPass    bool
	ShowSkip    bool
	ShowNoTests bool
	SmallScreen bool
	Slow        int
	TrimPath    string
	Width       int
	// Compare, when non-nil, maps package names to the coverage they had in a
	// previous run.
	Compare map[string]string
}

func (r *Reporter) style(seq string) ui.Style {
	return ui.NewStyle(seq, r.Color && r.Format != FormatMarkdown)
}

// status decorates a status label according to the active colour mode.
func (r *Reporter) status(s string) string {
	if !r.Color {
		return s
	}
	if r.Format == FormatMarkdown {
		switch s {
		case "PASS":
			return "🟢 " + s
		case "FAIL", "PANIC":
			return "🔴 " + s
		case "SKIP", "NOTEST":
			return "🟡 " + s
		}
		return s
	}
	switch s {
	case "PASS":
		return r.style("92").Render(s)
	case "FAIL", "PANIC":
		return r.style("91").Render(s)
	case "SKIP", "NOTEST":
		return r.style("93").Render(s)
	}
	return s
}

func (r *Reporter) sortedPackages(pkgs []*parse.Package) []*parse.Package {
	out := make([]*parse.Package, len(pkgs))
	copy(out, pkgs)
	switch r.Sort {
	case SortElapsed:
		sort.Slice(out, func(i, j int) bool { return out[i].Elapsed() > out[j].Elapsed() })
	case SortCover:
		sort.Slice(out, func(i, j int) bool { return out[i].CoverFloat() > out[j].CoverFloat() })
	default:
		sort.Slice(out, func(i, j int) bool { return out[i].DisplayName() < out[j].DisplayName() })
	}
	return out
}

// packageColumn is the package name as displayed inside tables.
func (r *Reporter) packageColumn(name string, pkgs []*parse.Package) string {
	if r.SmallScreen {
		if i := strings.LastIndex(name, "/"); i >= 0 {
			return name[i+1:]
		}
		return name
	}
	if r.TrimPath != "" {
		return strings.TrimPrefix(name, r.autoPrefix(pkgs))
	}
	return name
}

// autoPrefix returns the prefix to strip from package names.
func (r *Reporter) autoPrefix(pkgs []*parse.Package) string {
	if r.TrimPath != "auto" {
		return r.TrimPath
	}
	var names []string
	seen := map[string]bool{}
	for _, p := range pkgs {
		n := p.DisplayName()
		if !seen[n] {
			seen[n] = true
			names = append(names, n)
		}
	}
	if len(names) < 2 {
		return ""
	}
	prefix := names[0]
	for _, n := range names[1:] {
		k := 0
		for k < len(prefix) && k < len(n) && prefix[k] == n[k] {
			k++
		}
		prefix = prefix[:k]
	}
	if i := strings.LastIndex(prefix, "/"); i >= 0 {
		return prefix[:i+1]
	}
	return ""
}

// testName formats a test name, optionally splitting subtests across lines.
func (r *Reporter) testName(name string) string {
	if !r.SmallScreen || len(name) <= 32 {
		return name
	}
	parts := strings.Split(name, "/")
	var sb strings.Builder
	sb.WriteString(parts[0])
	for _, part := range parts[1:] {
		if len(part) <= 32 {
			sb.WriteString("\n /" + part)
			continue
		}
		for i := 0; i < len(part); i += 30 {
			end := i + 30
			if end > len(part) {
				end = len(part)
			}
			lead := "  "
			if i == 0 {
				lead = " /"
			}
			sb.WriteString("\n" + lead + part[i:end])
			if end < len(part) {
				sb.WriteString(" …")
			}
		}
	}
	return sb.String()
}

func (r *Reporter) newTable(headers []string, align []ui.Align) ui.Table {
	t := ui.Table{Headers: headers, Align: align}
	switch r.Format {
	case FormatPlain:
		t.Border = ui.HiddenBorder
	case FormatMarkdown:
		t.Border = ui.MarkdownBorder
	default:
		t.Border = ui.RoundedBorder
		t.BorderTop = true
		t.BorderBottom = true
	}
	return t
}

func (r *Reporter) skipInTestTable(p *parse.Package) bool {
	return p.NoTestFiles || p.NoTests || p.HasPanic
}

// testRows builds the test table rows for a single package.
func (r *Reporter) testRows(p *parse.Package, pkgs []*parse.Package, withPackage bool) [][]string {
	var tests []*parse.Test
	if r.ShowPass {
		passed := p.TestsByStatus(parse.ActionPass)
		sort.Slice(passed, func(i, j int) bool { return passed[i].Elapsed() > passed[j].Elapsed() })
		if r.Slow > 0 && len(passed) > r.Slow {
			passed = passed[:r.Slow]
		}
		tests = append(tests, passed...)
	}
	if r.ShowSkip {
		tests = append(tests, p.TestsByStatus(parse.ActionSkip)...)
	}
	tests = append(tests, p.TestsByStatus(parse.ActionFail)...)

	rows := make([][]string, 0, len(tests))
	for _, t := range tests {
		row := []string{
			r.status(strings.ToUpper(string(t.Status()))),
			fmt.Sprintf("%.2f", t.Elapsed()),
			r.testName(t.Name),
		}
		if withPackage {
			row = append(row, r.packageColumn(p.DisplayName(), pkgs))
		}
		rows = append(rows, row)
	}
	return rows
}

func (r *Reporter) renderTestTables(w io.Writer, pkgs []*parse.Package) {
	if r.Format == FormatMarkdown {
		for _, p := range pkgs {
			if r.skipInTestTable(p) {
				continue
			}
			rows := r.testRows(p, pkgs, false)
			if len(rows) == 0 {
				fmt.Fprintln(w)
				continue
			}
			pass, fail, skip := p.Counts()
			t := r.newTable([]string{"Status", "Elapsed", "Test"}, []ui.Align{ui.AlignCenter, ui.AlignCenter, ui.AlignLeft})
			t.Rows = rows
			fmt.Fprintf(w, "## 📦 Package **`%s`**\n\nTests: ✓ %d passed | %d skipped | %d failed\n\n<details>\n\n<summary>Click for test summary</summary>\n\n%s\n</details>\n\n\n",
				p.DisplayName(), pass, skip, fail, t.Render())
		}
		return
	}

	var rows [][]string
	for i, p := range pkgs {
		if r.skipInTestTable(p) {
			continue
		}
		rows = append(rows, r.testRows(p, pkgs, true)...)
		if i != len(pkgs)-1 {
			rows = append(rows, []string{"", "", "", ""})
		}
	}
	if len(rows) == 0 {
		return
	}
	t := r.newTable([]string{"Status", "Elapsed", "Test", "Package"}, []ui.Align{ui.AlignCenter, ui.AlignCenter, ui.AlignLeft, ui.AlignLeft})
	t.Rows = rows
	fmt.Fprintln(w, t.Render())
}

// failHeader extracts a "--- FAIL:" marker line, trimming the newline and
// halving the indentation preceding the marker.
func failHeader(line string) string {
	idx := strings.Index(line, "--- FAIL:")
	indent := strings.Count(line[:idx], " ") / 2
	return strings.Repeat(" ", indent) + strings.TrimSuffix(line[idx:], "\n")
}

// renderFailedTest returns the formatted output of one failed test.
func (r *Reporter) renderFailedTest(t *parse.Test) string {
	red := r.style("31")
	var header, body strings.Builder
	for _, e := range t.Events {
		if e.Action != parse.ActionOutput {
			continue
		}
		switch {
		case strings.Contains(e.Output, "--- FAIL:"):
			header.WriteString(red.Render(failHeader(e.Output)))
		case strings.HasPrefix(e.Output, "=== RUN   "),
			strings.HasPrefix(e.Output, "=== PAUSE "),
			strings.HasPrefix(e.Output, "=== CONT  "):
			continue
		default:
			body.WriteString(e.Output)
		}
	}
	out := header.String() + "\n"
	if body.Len() > 0 {
		out += "\n" + body.String() + "\n"
	}
	return out
}

func rootName(name string) string {
	return strings.Split(name, "/")[0]
}

// renderFailures writes the failed test output for a package.
func (r *Reporter) renderFailures(w io.Writer, p *parse.Package) {
	divider := strings.Repeat("─", r.Width) + "\n" + r.style("2").Render("") + strings.Repeat(" ", r.Width) + "\n"
	failed := p.SortedFailedTests()
	var sb strings.Builder
	for i, t := range failed {
		if i > 0 && rootName(failed[i-1].Name) != rootName(t.Name) {
			sb.WriteString(divider)
		}
		sb.WriteString(r.renderFailedTest(t))
	}

	if r.Format == FormatMarkdown {
		label := "FAIL"
		if r.Color {
			label = "🔴 FAIL"
		}
		fmt.Fprintf(w, "## %s • %s\n\n```\n%s```\n\n", label, p.DisplayName(), sb.String())
		return
	}
	red := r.style("91")
	content := red.Render(red.Render(p.StatusString())) + "  package: " + p.DisplayName()
	box := ui.Box(content, ui.ThickBorder, r.style("38;5;103"), 3)
	fmt.Fprintln(w, box)
	fmt.Fprintln(w)
	fmt.Fprint(w, sb.String())
}

// renderPanic writes the panic trace of a package.
func (r *Reporter) renderPanic(w io.Writer, p *parse.Package) {
	var header string
	if r.Format == FormatMarkdown {
		label := "PANIC"
		if r.Color {
			label = "🔴 PANIC"
		}
		header = "## " + label + " • " + p.Name
		if p.PanicTest != "" {
			header += " • " + p.PanicTest
		}
	} else {
		red := r.style("91")
		content := red.Render(red.Render("PANIC")) + "  package: " + p.Name
		if p.PanicTest != "" {
			content += " • " + p.PanicTest
		}
		header = ui.Box(content, ui.ThickBorder, r.style("38;5;103"), 3)
	}
	text := ui.RenderBlock(strings.Join(p.PanicOutput, ""), r.Width)
	fmt.Fprintln(w, ui.JoinVertical(header, text))
}

// summaryRow builds a summary table row for a package.
func (r *Reporter) summaryRow(p *parse.Package, pkgs []*parse.Package) []string {
	if p.HasPanic {
		return []string{r.status("PANIC"), "0.00s", r.packageColumn(p.Name, pkgs), "--", "--", "--", "--"}
	}
	elapsed := fmt.Sprintf("%.2fs", p.Elapsed())
	if p.NoTestFiles || p.NoTests {
		name := r.packageColumn(p.Name, pkgs)
		if p.NoTestFiles {
			name += "\n[no test files]"
		} else {
			name += "\n[no tests to run]"
		}
		return []string{r.status("NOTEST"), elapsed, name, "--", "--", "--", "--"}
	}
	if p.Cached {
		elapsed = "(cached)"
	}
	cover := "--"
	if p.Cover != "" {
		cover = p.Cover
		if r.Compare != nil {
			if prev, ok := r.Compare[p.DisplayName()]; ok {
				delta := p.CoverFloat() - coverFloat(prev)
				if delta > 0 {
					cover += fmt.Sprintf(" (+%.1f%%)", delta)
				} else {
					cover += fmt.Sprintf(" (%.1f%%)", delta)
				}
			} else {
				cover += " (-)"
			}
		}
	}
	pass, fail, skip := p.Counts()
	return []string{
		r.status(p.StatusString()),
		elapsed,
		r.packageColumn(p.DisplayName(), pkgs),
		cover,
		fmt.Sprint(pass),
		fmt.Sprint(fail),
		fmt.Sprint(skip),
	}
}

func coverFloat(s string) float64 {
	var f float64
	fmt.Sscanf(strings.TrimSuffix(s, "%"), "%g", &f)
	return f
}

func (r *Reporter) renderSummary(w io.Writer, pkgs []*parse.Package) {
	var panics, regular, notests [][]string
	for _, p := range pkgs {
		switch {
		case p.HasPanic:
			panics = append(panics, r.summaryRow(p, pkgs))
		case p.NoTestFiles || p.NoTests:
			if r.ShowNoTests {
				notests = append(notests, r.summaryRow(p, pkgs))
			}
		default:
			regular = append(regular, r.summaryRow(p, pkgs))
		}
	}
	t := r.newTable(
		[]string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"},
		[]ui.Align{ui.AlignCenter, ui.AlignCenter, ui.AlignLeft, ui.AlignCenter, ui.AlignCenter, ui.AlignCenter, ui.AlignCenter},
	)
	t.Rows = append(append(panics, regular...), notests...)
	fmt.Fprintln(w, t.Render())
}

// Render writes the complete report.
func (r *Reporter) Render(w io.Writer, sum *parse.Summary) {
	pkgs := r.sortedPackages(sum.Packages)

	if r.ShowPass || r.ShowSkip {
		r.renderTestTables(w, pkgs)
	}

	for _, p := range pkgs {
		switch {
		case p.HasPanic:
			r.renderPanic(w, p)
		case len(p.TestsByStatus(parse.ActionFail)) > 0:
			r.renderFailures(w, p)
		}
	}

	r.renderSummary(w, pkgs)
}
