{"command":"cd /workspace && cat > main.go <<'EOF'
// Command tparse summarises `go test -json` output.
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"

	"golang.org/x/term"

	"tparse/parse"
)

const usageText = `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`

const version = "(devel)"

// defaultWidth is used when the output is not a terminal.
const defaultWidth = 96

func main() {
	os.Exit(run())
}

func run() int {
	fs := flag.NewFlagSet("tparse", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Usage = func() {}

	var (
		showVersion      bool
		all, pass, skip  bool
		notests          bool
		smallScreen      bool
		slow             int
		sortKey          string
		noColor          bool
		format           string
		file             string
		follow           bool
		followOutput     string
		includeTimestamp bool
		progress         bool
		compare          string
		trimPath         string
	)
	fs.BoolVar(&showVersion, "v", false, "")
	fs.BoolVar(&showVersion, "version", false, "")
	fs.BoolVar(&all, "all", false, "")
	fs.BoolVar(&pass, "pass", false, "")
	fs.BoolVar(&skip, "skip", false, "")
	fs.BoolVar(&notests, "notests", false, "")
	fs.BoolVar(&smallScreen, "smallscreen", false, "")
	fs.IntVar(&slow, "slow", 0, "")
	fs.StringVar(&sortKey, "sort", "name", "")
	fs.BoolVar(&noColor, "nocolor", false, "")
	fs.StringVar(&format, "format", "basic", "")
	fs.StringVar(&file, "file", "", "")
	fs.BoolVar(&follow, "follow", false, "")
	fs.StringVar(&followOutput, "follow-output", "", "")
	fs.BoolVar(&includeTimestamp, "include-timestamp", false, "")
	fs.BoolVar(&progress, "progress", false, "")
	fs.StringVar(&compare, "compare", "", "")
	fs.StringVar(&trimPath, "trimpath", "", "")

	if err := fs.Parse(os.Args[1:]); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			fmt.Fprint(os.Stdout, usageText)
			return 0
		}
		fmt.Fprintln(os.Stderr, err)
		fmt.Fprint(os.Stderr, usageText)
		return 2
	}
	if showVersion {
		fmt.Fprintf(os.Stdout, "tparse version: %s\n", version)
		return 0
	}

	switch Format(format) {
	case FormatBasic, FormatPlain, FormatMarkdown:
	default:
		fmt.Fprintf(os.Stderr, "invalid option:%q. The -format flag must be one of: basic, plain or markdown\n", format)
		return 0
	}
	switch SortKey(sortKey) {
	case SortName, SortElapsed, SortCover:
	default:
		fmt.Fprintf(os.Stderr, "invalid option:%q. The -sort flag must be one of: name, elapsed or cover\n", sortKey)
		return 0
	}

	if _, ok := os.LookupEnv("NO_COLOR"); ok {
		noColor = true
	}

	var followWriter io.Writer
	if followOutput != "" {
		f, err := os.Create(followOutput)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 0
		}
		defer f.Close()
		followWriter = f
	} else if follow {
		followWriter = os.Stdout
	}

	var input io.Reader
	if file != "" {
		f, err := os.Open(file)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
		defer f.Close()
		input = f
	} else {
		info, err := os.Stdin.Stat()
		if err != nil || info.Mode()&os.ModeNamedPipe == 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			return 1
		}
		input = os.Stdin
	}

	rep := &Reporter{
		Color:       !noColor,
		Format:      Format(format),
		Sort:        SortKey(sortKey),
		ShowPass:    all || pass,
		ShowSkip:    all || skip,
		ShowNoTests: notests,
		SmallScreen: smallScreen,
		Slow:        slow,
		TrimPath:    trimPath,
		Width:       outputWidth(),
	}

	opts := parse.Options{
		Follow:           followWriter,
		IncludeTimestamp: includeTimestamp,
		ProgressStatus:   rep.status,
	}
	if progress {
		opts.Progress = os.Stdout
	}

	sum, err := parse.Process(input, opts)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	var compareWarning string
	if compare != "" {
		prev, warn := loadCompare(compare)
		rep.Compare = prev
		compareWarning = warn
	}

	rep.Render(os.Stdout, sum)
	if compareWarning != "" {
		fmt.Fprintln(os.Stderr, compareWarning)
	}
	return sum.ExitCode()
}

// loadCompare parses a previous run and returns its per-package coverage.
func loadCompare(path string) (map[string]string, string) {
	f, err := os.Open(path)
	if err != nil {
		return nil, "warning: failed to open against file: " + path
	}
	defer f.Close()
	sum, err := parse.Process(f, parse.Options{})
	if err != nil {
		return nil, "warning: failed to parse against file: " + path
	}
	out := map[string]string{}
	for _, p := range sum.Packages {
		out[p.DisplayName()] = p.Cover
	}
	return out, ""
}

// outputWidth returns the terminal width when stdout is a terminal,
// otherwise a fixed default.
func outputWidth() int {
	if term.IsTerminal(int(os.Stdout.Fd())) {
		w, _, err := term.GetSize(int(os.Stdout.Fd()))
		if err == nil {
			return w
		}
	}
	return defaultWidth
}
