	fs.BoolVar(&all, "all", false, "")
	fs.BoolVar(&pass, "pass", false, "")
	fs.BoolVar(&skip, "skip", false, "")
	fs.BoolVar(&notests, "notests", false, "")
	fs.BoolVar(&smallScreen, "smallscreen", false, "")
	fs.IntVar(&slow, "slow", 0, "")
	fs.StringVar(&sortKey, "sort", "name", "")
	fs.BoolVar(&noColor, "nocolor", false, "")
	fs.StringVar(&format, "format", "basic", "")
	fs.StringVar(&file, "file", "", "")
	fs.BoolVar(&follow, "follow", false, "")
	fs.StringVar(&followOutput, "follow-output", "", "")
	fs.BoolVar(&includeTimestamp, "include-timestamp", false, "")
	fs.BoolVar(&progress, "progress", false, "")
	fs.StringVar(&compare, "compare", "", "")
	fs.StringVar(&trimPath, "trimpath", "", "")

	if err := fs.Parse(os.Args[1:]); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			fmt.Fprint(os.Stdout, usageText)
			return 0
		}
		fmt.Fprintln(os.Stderr, err)
		fmt.Fprint(os.Stderr, usageText)
		return 2
	}
	if showVersion {
		fmt.Fprintf(os.Stdout, "tparse version: %s\n", version)
		return 0
	}

	switch Format(format) {
	case FormatBasic, FormatPlain, FormatMarkdown:
	default:
		fmt.Fprintf(os.Stderr, "invalid option:%q. The -format flag must be one of: basic, plain or markdown\n", format)
		return 0
	}
	switch SortKey(sortKey) {
	case SortName, SortElapsed, SortCover:
	default:
		fmt.Fprintf(os.Stderr, "invalid option:%q. The -sort flag must be one of: name, elapsed or cover\n", sortKey)
		return 0
	}

	if _, ok := os.LookupEnv("NO_COLOR"); ok {
		noColor = true
	}

	var followWriter io.Writer
	if followOutput != "" {
		f, err := os.Create(followOutput)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 0
		}
		defer f.Close()
		followWriter = f
	} else if follow {
		followWriter = os.Stdout
	}

	var input io.Reader
	if file != "" {
		f, err := os.Open(file)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
		defer f.Close()
		input = f
	} else {
		info, err := os.Stdin.Stat()
		if err != nil || info.Mode()&os.ModeNamedPipe == 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			return 1
		}
		input = os.Stdin
	}

	rep := &Reporter{
		Color:       !noColor,
		Format:      Format(format),
		Sort:        SortKey(sortKey),
		ShowPass:    all || pass,
		ShowSkip:    all || skip,
		ShowNoTests: notests,
		SmallScreen: smallScreen,
		Slow:        slow,
		TrimPath:    trimPath,
		Width:       outputWidth(),
	}

	opts := parse.Options{
		Follow:           followWriter,
		IncludeTimestamp: includeTimestamp,
		ProgressStatus:   rep.status,
	}
	if progress {
		opts.Progress = os.Stdout
	}

	sum, err := parse.Process(input, opts)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	var compareWarning string
	if compare != "" {
		prev, warn := loadCompare(compare)
		rep.Compare = prev
		compareWarning = warn
	}

	rep.Render(os.Stdout, sum)
	if compareWarning != "" {
		fmt.Fprintln(os.Stderr, compareWarning)
	}
	return sum.ExitCode()
}

// loadCompare parses a previous run and returns its per-package coverage.
func loadCompare(path string) (map[string]string, string) {
	f, err := os.Open(path)
	if err != nil {
		return nil, "warning: failed to open against file: " + path
	}
	defer f.Close()
	sum, err := parse.Process(f, parse.Options{})
	if err != nil {
		return nil, "warning: failed to parse against file: " + path
	}
	out := map[string]string{}
	for _, p := range sum.Packages {
		out[p.DisplayName()] = p.Cover
	}
	return out, ""
}

// outputWidth returns the terminal width when stdout is a terminal,
// otherwise a fixed default.
func outputWidth() int {
	if term.IsTerminal(int(os.Stdout.Fd())) {
		w, _, err := term.GetSize(int(os.Stdout.Fd()))
		if err == nil {
			return w
		}
	}
	return defaultWidth
}
