// resolveTrimPrefix returns the prefix to strip from package names. With
// "auto" the longest common directory prefix of all packages is used.
func (r *Reporter) resolveTrimPrefix(pkgs []*parse.Package) string {
	if r.TrimPath != "auto" {
		return r.TrimPath
	}
	var names []string
	seen := map[string]bool{}
	for _, p := range pkgs {
		n := p.DisplayName()
		if !seen[n] {
			seen[n] = true
			names = append(names, n)
		}
	}
	if len(names) < 2 {
		return ""
	}
	prefix := names[0]
	for _, n := range names[1:] {
		k := 0
		for k < len(prefix) && k < len(n) && prefix[k] == n[k] {
			k++
		}
		prefix = prefix[:k]
	}
	if i := strings.LastIndex(prefix, "/"); i >= 0 {
		return prefix[:i+1]
	}
	return ""
}

